import{R as e,e as o,f as n,U as r}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"Marketo","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/marketo.md","filePath":"integrations/crm/marketo.md","lastUpdated":1775908585000}'),a={name:"integrations/crm/marketo.md"};function i(s,t,l,g,c,h){return o(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="marketo" tabindex="-1">Marketo <a class="header-anchor" href="#marketo" aria-label="Permalink to &quot;Marketo&quot;">​</a></h1><p>Follow the below steps to connect to the Marketo API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Marketo as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-marketo-api" tabindex="-1">Step 2. Connect to the Marketo API <a class="header-anchor" href="#step-2-connect-to-the-marketo-api" aria-label="Permalink to &quot;Step 2. Connect to the Marketo API&quot;">​</a></h3><ol><li>Go to <a href="https://business.adobe.com/au/products/marketo.html" target="_blank">Marketo</a> and login to your account.</li><li>Under <strong>Integration</strong>, select <strong>LaunchPoint</strong>.</li><li>Click <strong>New</strong> → <strong>New Service</strong>.</li><li>Enter a name for the service and select <strong>Custom</strong> as the service type.</li><li>Choose the appropriate API-only user and click <strong>Create</strong>.</li><li>Still in the Admin panel, go to <strong>Web Services</strong> under <strong>Integration</strong>.</li><li>Under <strong>REST API</strong>, copy the <strong>Endpoint URL</strong> and paste in the <strong>API Domain</strong> field in Formie.</li><li>Copy the <strong>Client ID</strong> from Marketo and paste in the <strong>Client ID</strong> field in Formie.</li><li>Copy the <strong>Client Secret</strong> from Marketo and paste in the <strong>Client Secret</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to Marketo, where you must approve Formie to access your Marketo account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const m=e(a,[["render",i]]);export{p as __pageData,m as default};
